#include <stdio.h>

int main() {
    // 문자열 선언 (자동으로 끝에 \0이 붙음)
    char str[] = "Code";

    printf("String: %s\n", str);
    printf("Size:   %lu\n", sizeof(str));

    // 메모리 하나하나 확인
    printf("[%c] [%c] [%c] [%c] [%d]\n", 
           str[0], str[1], str[2], str[3], str[4]);

    return 0;
}
